function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function button(label,action,arg='',cls='',native=''){return `<button class="${cls}" data-action="${action}" data-arg="${esc(arg)}"${nativeAttr(native)}>${label}</button>`}
function switcher(label,key,hint='',native=''){return `<div class="choice-row"><div><div>${esc(label)}</div>${hint?`<small>${esc(hint)}</small>`:''}</div><button class="switch" role="switch" aria-label="${esc(label)}" aria-checked="${!!draft[key]}" data-action="toggle" data-arg="${key}"${nativeAttr(native)}></button></div>`}
