function validateDraft(){if(!draft)return '没有选中对象';if(!draft.name.trim())return '名称不能为空';if(type==='character'&&((typeof draft.depth!=='number'||!Number.isInteger(draft.depth))||draft.depth<0||draft.depth>9999))return '注入深度需为 0–9999 的整数';if(type==='character'&&(!Number.isFinite(+draft.talkativeness)||draft.talkativeness<0||draft.talkativeness>1))return '健谈度需在 0–1 之间';if(type==='group'&&((typeof draft.delay!=='number'||!Number.isInteger(draft.delay))||draft.delay<1||draft.delay>999))return '自动模式延时需为 1–999 秒的整数';return ''}
function saveDraft(){const error=validateDraft();if(error){toast(error);return false}const a=data(),i=a.findIndex(x=>x.id===selectedId);if(i<0){toast('对象已不存在，保留草稿');return false}a[i]=clone(draft);revision++;batchPlan=null;updateStatus();toast('已保存到本次样稿；未写入宿主');return true}
