function planBatch(){if(dirty()){toast('先保存或放弃当前草稿，再预览批量修改');return}if(!selection.size){toast('先从列表多选对象');return}if(['tag-add','tag-remove'].includes(batchOp)&&!batchValue.trim()){toast('先填写标签');return}if(batchOp==='persona'){openPanel('identity');return}const targets=data().filter(x=>selection.has(x.id));const rows=targets.map(x=>{let y=clone(x);if(batchOp==='fav')y.fav=!y.fav;if(batchOp==='tag-add')y.tags=[...new Set([...y.tags,batchValue.trim()])];if(batchOp==='tag-remove')y.tags=y.tags.filter(t=>t!==batchValue.trim());if(batchOp==='tag-clear')y.tags=[];if(batchOp==='tag-import')y.tags=[...new Set([...y.tags,...String(y.tagsText||'').split(/[,，]/).map(s=>s.trim()).filter(Boolean)])];return {id:x.id,before:x,after:y}});batchPlan={fingerprint:batchFingerprint(),rows,op:batchOp};renderDock()}
