document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){const k=el.dataset.field;draft[k]=['depth','delay','talkativeness'].includes(k)?(el.value===''?'':Number(el.value)):el.value;if(k==='talkativeness'&&$('#talk-output'))$('#talk-output').textContent=Math.round(draft[k]*100)+'%';updateStatus();return}if(el.dataset.greeting!==undefined){draft.alternate_greetings[+el.dataset.greeting]=el.value;updateStatus();return}if(el.dataset.override){panelState.value[el.dataset.override]=el.value;return}if(el.id==='search'){search=el.value;rerenderFocused('search')}if(el.id==='member-search'){memberSearch=el.value;rerenderFocused('member-search')}if(el.id==='history-search'){historySearch=el.value;$('#session-list').innerHTML=sessionRows()}if(el.id==='candidate-search')$$('[data-candidate-name]').forEach(n=>n.hidden=!n.dataset.candidateName.toLowerCase().includes(el.value.toLowerCase()));if(el.id==='audit-search')$('#audit-results').innerHTML=auditRows(el.value);if(el.id==='batch-value'){batchValue=el.value;batchPlan=null;const pos=el.selectionStart;renderDock();$('#batch-value').focus();$('#batch-value').setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.select){if(el.checked)selection.add(el.dataset.select);else selection.delete(el.dataset.select);batchPlan=null;render();return}if(el.dataset.candidate){if(el.checked)panelState.chosen.add(el.dataset.candidate);else panelState.chosen.delete(el.dataset.candidate);return}if(el.id==='sort'){sort=el.value;if(sort==='random')randomOrder=Object.fromEntries(data().map(x=>[x.id,Math.random()]));render()}if(el.id==='batch-op'){batchOp=el.value;batchPlan=null;renderDock()}if(el.dataset.field&&el.tagName==='SELECT'){draft[el.dataset.field]=el.value;render()}});
let dragged=null;document.addEventListener('dragstart',e=>{const n=e.target.closest('[data-member]');if(!n||e.target.closest('button,input,textarea'))return;dragged=n.dataset.member;n.classList.add('dragging');e.dataTransfer?.setData('text/plain',dragged)});document.addEventListener('dragover',e=>{const n=e.target.closest('[data-member]');if(n&&dragged){e.preventDefault();n.classList.add('drag-over')}});document.addEventListener('dragleave',e=>e.target.closest('[data-member]')?.classList.remove('drag-over'));document.addEventListener('drop',e=>{const n=e.target.closest('[data-member]');if(n&&dragged){e.preventDefault();moveIn(draft.members,draft.members.indexOf(dragged),draft.members.indexOf(n.dataset.member));dragged=null;render()}});document.addEventListener('dragend',()=>{dragged=null;$$('.dragging,.drag-over').forEach(x=>x.classList.remove('dragging','drag-over'))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panelState)closePanel();if(e.key==='Tab'&&panelState){const xs=$$('#panel-root button:not(:disabled),#panel-root input,#panel-root textarea,#panel-root select').filter(x=>x.offsetParent!==null),first=xs[0],last=xs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue=''}});window.addEventListener('resize',()=>{if(innerWidth>760&&!showDetail){showDetail=true;render()}});
window.characterGroupPreview={snapshot:()=>clone(store),getDraft:()=>clone(draft),isDirty:dirty,getCatalog:()=>clone(catalog),identity:()=>({status:'unavailable',reason:'reserved-not-connected',capabilities:[]})};render();
let touchDrag=null;
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag-handle]');if(!h||e.button>0||panelState)return;e.preventDefault();touchDrag={id:h.dataset.dragHandle,target:h.dataset.dragHandle,pointerId:e.pointerId,handle:h};h.setPointerCapture(e.pointerId);h.closest('.member').classList.add('dragging')});
document.addEventListener('pointermove',e=>{if(!touchDrag||touchDrag.pointerId!==e.pointerId)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-member]');$$('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(target){touchDrag.target=target.dataset.member;target.classList.add('drag-over')}});
function finishTouchDrag(e,cancel=false){if(!touchDrag||touchDrag.pointerId!==e.pointerId)return;const d=touchDrag;touchDrag=null;if(!cancel&&type==='group'){moveIn(draft.members,draft.members.indexOf(d.id),draft.members.indexOf(d.target));render()}else $$('.dragging,.drag-over').forEach(x=>x.classList.remove('dragging','drag-over'))}
document.addEventListener('pointerup',e=>finishTouchDrag(e));document.addEventListener('pointercancel',e=>finishTouchDrag(e,true));document.addEventListener('lostpointercapture',e=>finishTouchDrag(e,true));
